3	declare( strict_types = 1 );
4	
5	namespace WPMedia\McpManager\Plugin;
6	
7	use League\Container\Container;
8	
9	class Plugin {
10	
11		private Container $container;
12		private string    $plugin_file;
13	
14		public function __construct( Container $container, string $plugin_file ) {
15			$this->container   = $container;
16			$this->plugin_file = $plugin_file;
17	
18			$plugin_dir = plugin_dir_path( $plugin_file );
19			$plugin_url = plugin_dir_url( $plugin_file );
20	
21			$this->container->addShared( 'plugin.dir', static fn() => $plugin_dir );
22			$this->container->addShared( 'plugin.url', static fn() => $plugin_url );
23		}
24	
25		public function init(): void {
26			$provider_classes = require dirname( $this->plugin_file ) . '/config/providers.php';
27			$providers        = [];
28	
29			foreach ( $provider_classes as $class ) {
30				$provider    = new $class();
31				$providers[] = $provider;
32				$this->container->addServiceProvider( $provider );
33			}
34	
35			foreach ( $providers as $provider ) {
36				if ( ! method_exists( $provider, 'get_subscribers' ) ) {
37					continue;
38				}
39				foreach ( $provider->get_subscribers() as $subscriber_id ) {
40					$subscriber = $this->container->get( $subscriber_id );
41					if ( method_exists( $subscriber, 'register' ) ) {
42						$subscriber->register();
43					}
44				}
45			}
46		}
47	}
