3	declare( strict_types = 1 );
4	
5	namespace WPMedia\McpManager\Abilities;
6	
7	class AbilityReader {
8	
9		/**
10		 * Returns all registered abilities grouped by plugin namespace.
11		 *
12		 * @return array<string, array{label: string, count: int, abilities: list<array>}>
13		 */
14		public function get_grouped(): array {
15			if ( ! function_exists( 'wp_get_abilities' ) ) {
16				return [];
17			}
18	
19			$abilities = wp_get_abilities();
20			$groups    = [];
21	
22			foreach ( $abilities as $ability ) {
23				$name      = $ability->get_name();
24				$namespace = strstr( $name, '/', true ) ?: $name;
25	
26				if ( ! isset( $groups[ $namespace ] ) ) {
27					$groups[ $namespace ] = [
28						'label'     => $this->namespace_to_label( $namespace ),
29						'abilities' => [],
30					];
31				}
32	
33				$meta        = $ability->get_meta();
34				$annotations = $meta['annotations'] ?? [];
35	
36				$groups[ $namespace ]['abilities'][] = [
37					'name'        => $name,
38					'label'       => $ability->get_label(),
39					'description' => $ability->get_description(),
40					'category'    => $ability->get_category(),
41					'show_in_rest'=> ! empty( $meta['show_in_rest'] ),
42					'mcp_public'  => ! empty( $meta['mcp']['public'] ),
43					'mcp_type'    => $meta['mcp']['type'] ?? 'tool',
44					'readonly'    => $annotations['readonly'] ?? null,
45					'destructive' => $annotations['destructive'] ?? null,
46					'idempotent'  => $annotations['idempotent'] ?? null,
47				];
48			}
49	
50			ksort( $groups );
51	
52			return $groups;
53		}
54	
55		/**
56		 * Returns all registered ability categories keyed by slug.
57		 *
58		 * @return array<string, array{label: string, description: string}>
59		 */
60		public function get_categories(): array {
61			if ( ! function_exists( 'wp_get_ability_categories' ) ) {
62				return [];
63			}
64	
65			$result = [];
66	
67			foreach ( wp_get_ability_categories() as $slug => $category ) {
68				$result[ $slug ] = [
69					'label'       => $category->get_label(),
70					'description' => $category->get_description(),
71				];
72			}
73	
74			return $result;
75		}
76	
77		/** Returns the abilities REST endpoint URL. */
78		public function get_rest_url(): string {
79			return rest_url( 'wp-abilities/v1/abilities' );
80		}
81	
82		/** Returns the total count of registered abilities. */
83		public function get_total_count(): int {
84			if ( ! function_exists( 'wp_get_abilities' ) ) {
85				return 0;
86			}
87	
88			return count( wp_get_abilities() );
89		}
90	
91		/** Returns whether the WP Abilities API is available. */
92		public function has_abilities_api(): bool {
93			return function_exists( 'wp_get_abilities' );
94		}
95	
96		private function namespace_to_label( string $namespace ): string {
97			return ucwords( str_replace( [ '-', '_' ], ' ', $namespace ) );
98		}
99	}
