20			$abilities    = $this->ability_reader->get_grouped();
21			$categories   = $this->ability_reader->get_categories();
22			$rest_url     = $this->ability_reader->get_rest_url();
23			$total_count  = $this->ability_reader->get_total_count();
24			$has_api      = $this->ability_reader->has_abilities_api();
